/* source: curated */
/* algorithm: ime_vmadot_4x4x8 */
/* accuracy_class: bit_exact */
/* origin: generated by pipeline/generate_kernels.py via Codex (gpt-5.6-sol),
 *   second round -- the first was correct but packed per output tile and lost
 *   to RVV by 6.5x. See the measurements at the bottom of this header.
 *
 * FOUR MEASURED FACTS THIS KERNEL RESTS ON:
 *   1. micro-tile 4x4x8, hardware-forced (vl*SEW indexes the MAC table, not
 *      VLEN). vsetvli vl=32,e8,m1 must be live AT the instruction or SIGILL.
 *   2. vmadot ACCUMULATES: vd += A . B^T. Confirmed by issuing identical
 *      operands twice and watching every result double -- which is what makes
 *      K>8 a loop rather than impossible.
 *   3. the 16 int32 results are ROW-MAJOR across the pair (vd, vd+1):
 *      element e is C[e/4][e%4]. scripts/k1_ime_accumulator_probe.c.
 *   4. CLUSTER 0 ONLY. Harts 4-7 exit 132 (SIGILL).
 *
 * WHY IT PACKS THE WAY IT DOES, which is the whole performance story. vmadot
 * needs its operands as 4x8 tiles, and the naive place to build them is inside
 * the (m0, n0) loop -- which makes repacking O(M*N*K/4) against O(M*N*K) MACs
 * and leaves the MAC unit idle behind its own data movement. Instead: pack A
 * once per m-tile block, run n0 outermost packing each B panel once, and reuse
 * both across the inner m loop. M*K + N*K instead of M*N*K/4.
 *
 * The requantize tail is scalar, as in the RVV kernel: the oracle rounds
 * half-away-from-zero (roundf) while RVV float conversion rounds to
 * nearest-even, so a vectorized tail loses max_abs_err=0.
 *
 * MEASURED ON THE BOARD (hart 3, GCC 14.3), against
 * kernels/rvv/rvv_matmul_s8_rvv_k_reduce_n_lanes.c back to back:
 *
 *   shape                    RVV        IME      IME speedup
 *   M=7   K=512 N=512      0.982 ms   3.978 ms     0.25x   loses
 *   M=64  K=512 N=512      8.966 ms   6.263 ms     1.43x
 *   M=128 K=256 N=256 tb1  5.998 ms   2.609 ms     2.30x
 *
 * IT LOSES AT SMALL M AND THAT IS STRUCTURAL, not a defect: M=7 fills two
 * 4-row tiles with one row of eight wasted, and amortizes the B-panel packing
 * over only two m-tiles. Attention's M=8 is in that regime; a transformer MLP
 * block is not. This is why `ime` is an ALTERNATIVE the scheduler chooses per
 * dispatch rather than a backend for a whole model.
 *
 * The ceiling, measured with registers preloaded and no memory traffic:
 * vmadot sustains 34.02 GMAC/s against 10.22 GMAC/s for the vwmul.vv +
 * vwadd.wv i32 sequence a bit-exact RVV matmul requires -- 3.33x. The 2.30x
 * above is 69% of that.
 */


void kernel_matmul_s8(const int8_t *a, const int8_t *b, int8_t *output, int M, int K, int N, float scale_a, float scale_b, float scale_out, int transpose_b, float scale_div, int activation_min, int activation_max) {
    if (M <= 0 || N <= 0) {
        return;
    }

    int m_tiles = (M + 3) / 4;
    int k_slabs = K > 0 ? (K + 7) / 8 : 1;
    size_t bytes_per_m_tile = (size_t)k_slabs * 32u;
    size_t max_a_pack_bytes = 256u * 1024u;
    int block_m_tiles = (int)(max_a_pack_bytes / bytes_per_m_tile);

    if (block_m_tiles < 1) {
        block_m_tiles = 1;
    }
    if (block_m_tiles > m_tiles) {
        block_m_tiles = m_tiles;
    }

    int8_t packed_a[(size_t)block_m_tiles * bytes_per_m_tile];
    int8_t packed_b[(size_t)k_slabs * 32u];
    int32_t tile_output[16];
    float total = (scale_a * scale_b) / (scale_out * scale_div);

    for (int mt_outer = 0; mt_outer < m_tiles;
         mt_outer += block_m_tiles) {
        int current_m_tiles = m_tiles - mt_outer;
        if (current_m_tiles > block_m_tiles) {
            current_m_tiles = block_m_tiles;
        }

        for (int mt = 0; mt < current_m_tiles; mt++) {
            int m0 = (mt_outer + mt) * 4;

            for (int ks = 0; ks < k_slabs; ks++) {
                int k0 = ks * 8;
                int8_t *dst =
                    packed_a + ((size_t)mt * (size_t)k_slabs +
                                (size_t)ks) * 32u;

                for (int i = 0; i < 4; i++) {
                    int row = m0 + i;

                    for (int q = 0; q < 8; q++) {
                        int k = k0 + q;
                        dst[i * 8 + q] =
                            (row < M && k < K)
                                ? a[(size_t)row * (size_t)K + (size_t)k]
                                : (int8_t)0;
                    }
                }
            }
        }

        for (int n0 = 0; n0 < N; n0 += 4) {
            for (int ks = 0; ks < k_slabs; ks++) {
                int k0 = ks * 8;
                int8_t *dst = packed_b + (size_t)ks * 32u;

                for (int j = 0; j < 4; j++) {
                    int col = n0 + j;

                    for (int q = 0; q < 8; q++) {
                        int k = k0 + q;
                        int8_t value = 0;

                        if (col < N && k < K) {
                            if (transpose_b) {
                                value = b[(size_t)col * (size_t)K +
                                          (size_t)k];
                            } else {
                                value = b[(size_t)k * (size_t)N +
                                          (size_t)col];
                            }
                        }
                        dst[j * 8 + q] = value;
                    }
                }
            }

            for (int mt = 0; mt < current_m_tiles; mt++) {
                int m0 = (mt_outer + mt) * 4;
                const int8_t *a_tile =
                    packed_a + (size_t)mt * bytes_per_m_tile;
                const int8_t *b_tile = packed_b;
                int slabs = k_slabs;
                size_t n32 = 32;
                size_t n8 = 8;

                __asm__ volatile(
                    "vsetvli t0, %[n32], e8, m1, ta, ma\n\t"
                    "vmv.v.i v8, 0\n\t"
                    "vmv.v.i v9, 0\n\t"
                    "1:\n\t"
                    "vsetvli t0, %[n32], e8, m1, ta, ma\n\t"
                    "vle8.v v0, (%[pa])\n\t"
                    "vle8.v v4, (%[pb])\n\t"
                    "vsetvli t0, %[n32], e8, m1, ta, ma\n\t"
                    ".insn r 0x2b, 3, 0x71, x8, x0, x4\n\t"
                    "addi %[pa], %[pa], 32\n\t"
                    "addi %[pb], %[pb], 32\n\t"
                    "addi %[ks], %[ks], -1\n\t"
                    "bnez %[ks], 1b\n\t"
                    "vsetvli t0, %[n8], e32, m1, ta, ma\n\t"
                    "vse32.v v8, (%[o0])\n\t"
                    "vse32.v v9, (%[o1])\n\t"
                    : [pa] "+r"(a_tile), [pb] "+r"(b_tile),
                      [ks] "+r"(slabs)
                    : [o0] "r"(tile_output),
                      [o1] "r"(tile_output + 8),
                      [n32] "r"(n32), [n8] "r"(n8)
                    : "t0", "memory", "v0", "v4", "v8", "v9");

                for (int i = 0; i < 4 && m0 + i < M; i++) {
                    for (int j = 0; j < 4 && n0 + j < N; j++) {
                        int32_t acc = tile_output[i * 4 + j];
                        int32_t scaled =
                            (int32_t)roundf((float)acc * total);

                        if (scaled < activation_min) {
                            scaled = activation_min;
                        }
                        if (scaled > activation_max) {
                            scaled = activation_max;
                        }

                        output[(size_t)(m0 + i) * (size_t)N +
                               (size_t)(n0 + j)] = (int8_t)scaled;
                    }
                }
            }
        }
    }
}
